create or replace function public.start_ending_rental(p_relationship_id uuid) returns public.rental_relationships language plpgsql security definer set search_path='' as $$ declare v_r public.rental_relationships; begin select * into v_r from public.rental_relationships where id=p_relationship_id for update; if not found then raise exception 'RENTAL_NOT_FOUND'; end if; if public.has_administration_management_role(v_r.administration_id) is not true then raise exception 'ADMINISTRATION_ROLE_REQUIRED'; end if; if v_r.status<>'ACTIVE' then raise exception 'RENTAL_NOT_ACTIVE'; end if; update public.rental_relationships set status='ENDING',ending_started_at=now() where id=v_r.id returning * into v_r; return v_r; end $$;
create or replace function public.end_rental(p_relationship_id uuid,p_actual_end_date date default current_date) returns public.rental_relationships language plpgsql security definer set search_path='' as $$ declare v_r public.rental_relationships; begin select * into v_r from public.rental_relationships where id=p_relationship_id for update; if not found then raise exception 'RENTAL_NOT_FOUND'; end if; if public.has_administration_management_role(v_r.administration_id) is not true then raise exception 'ADMINISTRATION_ROLE_REQUIRED'; end if; if v_r.status not in('ACTIVE','ENDING') then raise exception 'RENTAL_NOT_ENDABLE'; end if; if p_actual_end_date<v_r.real_start_date then raise exception 'END_BEFORE_START'; end if; update public.rental_relationships set status='ENDED',actual_end_date=p_actual_end_date,ended_at=now() where id=v_r.id returning * into v_r; update public.rental_participants set status='ENDED',ends_on=coalesce(ends_on,p_actual_end_date) where rental_relationship_id=v_r.id and status='ACTIVE'; delete from public.rental_subject_occupancies where rental_relationship_id=v_r.id; return v_r; end $$;
comment on function public.start_ending_rental(uuid) is 'Closure operation intentionally allowed to an authorized administration role even when management subscription access has expired.';
comment on function public.end_rental(uuid,date) is 'Closure operation intentionally allowed to an authorized administration role even when management subscription access has expired. Outstanding debt may remain after ENDED.';